# -*- coding: utf-8 -*-
# Writes tools/shots/smoke_sheet.txt: 8 viewpoints around the shelter (docs/design/17 3.2.1), noon and dusk.
# Run the script twice (once normally, once with env SKYABYSS_NO_SMOKE_COLUMN=1) and copy the pngs in between;
# python tools/sheets/smoke_sheet.py then builds docs/review/previews/smoke_sheet.png.
import math
import pathlib

CX, CZ = 132, 136  # shelter of the world 'smoke_sheet' (dev opening info)
LOOK_Y = 125
spots = [(0, 170), (45, 230), (90, 170), (135, 230), (180, 170), (225, 230), (270, 170), (315, 230)]
out = [
    "# smoke column sheet (generated by tools/gen/shots/gen_smoke_sheet_shots.py)",
    "world smoke_sheet normal",
    "size 960 540",
    "timeout 1500",
    "render 12",
    "clouds off",
    "waitchunks",
    "wait 60",
    "cmd skyabyss cinematic stop",
    "cmd weather clear",
    "cmd gamerule doDaylightCycle false",
    "cmd gamerule doWeatherCycle false",
    "cmd gamemode spectator",
    "hud off",
]
for i, (deg, d) in enumerate(spots):
    x = round(CX + d * math.cos(math.radians(deg)))
    z = round(CZ + d * math.sin(math.radians(deg)))
    out += [
        "echo === spot %d at %d %d" % (i, x, z),
        "cmd time set 6000",
        "cmd spreadplayers %d %d 0 1 false @s" % (x, z),
        "waitchunks 400",
        "wait 20",
        "cmd execute if biome ~ ~ ~ #minecraft:is_forest",
        "cmd execute if biome ~ ~ ~ #minecraft:is_hill",
        "cmd execute if biome ~ ~ ~ #minecraft:is_mountain",
        "cmd execute if biome ~ ~ ~ minecraft:plains",
        "cmd execute positioned over motion_blocking_no_leaves run tp @s ~ ~1 ~ facing %d %d %d" % (CX, LOOK_Y, CZ),
        "cmd data get entity @s Pos",
        "wait 30",
        "shot s%d_noon" % i,
        "cmd time set 12300",
        "wait 30",
        "shot s%d_dusk" % i,
    ]
(pathlib.Path(__file__).resolve().parents[2] / "shots").joinpath("smoke_sheet.txt").write_text("\n".join(out) + "\n", encoding="utf-8")
